  "motion": {
    "source": "src/ui/motion.tsx",
    "exports": [
      {
        "name": "MotionPreset",
        "kind": "type",
        "description": "Motion presets — enter/exit/hover recipes expressed as token-driven class strings on top of `tw-animate-css` (zero runtime deps). The `<Motion>` primitive plays an enter recipe once on mount; the exported maps and helpers let you drop the same recipes onto anything else (a Radix `data-[state]` element, a hand-rolled transition). Timing rides the CSS custom properties tw-animate-css reads: - default duration/easing come from the static `duration-*`/`ease-*` classes baked into `motionEnter`, - the `duration`/`delay` props override them per-instance via `--tw-animation-duration` / `--tw-animation-delay` (no arbitrary Tailwind class is generated at runtime, so it works with any value). Everything degrades under `prefers-reduced-motion`: the enter animation is dropped (content shows immediately) and hover transitions are disabled.",
        "definition": "type MotionPreset = | \"fade\" | \"fade-up\" | \"fade-down\" | \"fade-left\" | \"fade-right\" | \"scale\" | \"blur\""
      },
      {
        "name": "MotionHover",
        "kind": "type",
        "definition": "type MotionHover = \"lift\" | \"sink\" | \"scale\" | \"glow\""
      },
      {
        "name": "motionEnterPresets",
        "kind": "utility",
        "description": "Enter recipes: tw-animate-css `animate-in` sets the keyframe `from` state, the element animates to its natural rendered state."
      },
      {
        "name": "motionExitPresets",
        "kind": "utility",
        "description": "Exit recipes: the mirror of each enter preset, for `animate-out` on a Radix `data-[state=closed]` element."
      },
      {
        "name": "motionHoverPresets",
        "kind": "utility",
        "description": "Hover recipes: plain Tailwind transitions, no keyframes."
      },
      {
        "name": "motionEnter",
        "kind": "utility",
        "description": "Build the class string for an enter recipe (plays on mount).",
        "signature": "(preset: MotionPreset, className?: string): string"
      },
      {
        "name": "motionExit",
        "kind": "utility",
        "description": "Build the class string for an exit recipe (pair with `animate-out`).",
        "signature": "(preset: MotionPreset, className?: string): string"
      },
      {
        "name": "motionHover",
        "kind": "utility",
        "description": "Build the class string for a hover recipe.",
        "signature": "(hover: MotionHover, className?: string): string"
      },
      {
        "name": "MotionProps",
        "kind": "type",
        "definition": "interface MotionProps extends React.ComponentProps<\"div\"> { /** Enter recipe to play on mount. Default `\"fade\"`. */ preset?: MotionPreset /** Optional hover recipe applied to the same element. */ hover?: MotionHover /** Enter duration in milliseconds. Overrides the 500ms default. */ duration?: number /** Enter delay in milliseconds — the knob for staggering a list. */ delay?: number /** Merge props onto the single child instead of rendering a wrapper. */ asChild?: boolean }"
      },
      {
        "name": "Motion",
        "kind": "component",
        "propsType": "MotionProps",
        "props": [
          {
            "name": "preset",
            "type": "MotionPreset",
            "required": false,
            "default": "\"fade\"",
            "description": "Enter recipe to play on mount. Default `\"fade\"`."
          },
          {
            "name": "hover",
            "type": "MotionHover",
            "required": false,
            "description": "Optional hover recipe applied to the same element."
          },
          {
            "name": "duration",
            "type": "number",
            "required": false,
            "description": "Enter duration in milliseconds. Overrides the 500ms default."
          },
          {
            "name": "delay",
            "type": "number",
            "required": false,
            "description": "Enter delay in milliseconds — the knob for staggering a list."
          },
          {
            "name": "asChild",
            "type": "boolean",
            "required": false,
            "default": "false",
            "description": "Merge props onto the single child instead of rendering a wrapper."
          }
        ]
      }
    ]
  },
