  "scroll-reveal": {
    "source": "src/ui/scroll-reveal.tsx",
    "exports": [
      {
        "name": "ScrollRevealProps",
        "kind": "type",
        "description": "Plays a motion enter recipe when the element scrolls into view (rather than on mount like `<Motion>`). Built on the `useInView` IntersectionObserver hook and the motion engine's recipes, so it shares the same presets, timing and prefers-reduced-motion fallback. SSR- and no-JS-safe: it renders visible until it has mounted and armed, so search engines and scriptless clients always see the content.",
        "definition": "interface ScrollRevealProps extends React.ComponentProps<\"div\">, Pick<UseInViewOptions, \"once\" | \"amount\" | \"margin\" | \"root\"> { /** Enter recipe to play when revealed. Default `\"fade-up\"`. */ preset?: MotionPreset /** Reveal duration in milliseconds. Overrides the 500ms default. */ duration?: number /** Reveal delay in milliseconds — the knob for staggering a group. */ delay?: number /** Merge props onto the single child instead of rendering a wrapper. */ asChild?: boolean }"
      },
      {
        "name": "ScrollReveal",
        "kind": "component",
        "propsType": "ScrollRevealProps",
        "props": [
          {
            "name": "preset",
            "type": "MotionPreset",
            "required": false,
            "default": "\"fade-up\"",
            "description": "Enter recipe to play when revealed. Default `\"fade-up\"`."
          },
          {
            "name": "duration",
            "type": "number",
            "required": false,
            "description": "Reveal duration in milliseconds. Overrides the 500ms default."
          },
          {
            "name": "delay",
            "type": "number",
            "required": false,
            "description": "Reveal delay in milliseconds — the knob for staggering a group."
          },
          {
            "name": "asChild",
            "type": "boolean",
            "required": false,
            "default": "false",
            "description": "Merge props onto the single child instead of rendering a wrapper."
          },
          {
            "name": "once",
            "type": "boolean",
            "required": false,
            "default": "true",
            "description": "Stop observing after the first time the element enters view. Default `true`."
          },
          {
            "name": "amount",
            "type": "number",
            "required": false,
            "default": "0.3",
            "description": "Fraction of the element that must be visible to count as in view (0–1). Default `0.3`."
          },
          {
            "name": "margin",
            "type": "string",
            "required": false,
            "default": "\"0px\"",
            "description": "IntersectionObserver `rootMargin`, e.g. `\"-10% 0px\"`. Default `\"0px\"`."
          }
        ]
      }
    ]
  },
